#include <Arduino.h>
#include <SPI.h>
#include <esp_wifi.h>
#include <WiFi.h>

// Dane Twojej sieci Wi-Fi
const char* ssid = "NAZWA_TWOJEJ_SIECI_WIFI";
const char* password = "HASLO_TWOJEJ_SIECI_WIFI";

// Piny LilyGO T-Embed
#define PIN_POWER_EN  46
#define PIN_ANT_SW0   16
#define PIN_ANT_SW1   17
#define CC1101_SPI_CLK  11
#define CC1101_SPI_MOSI 9
#define CC1101_SPI_MISO 10
#define CC1101_SPI_CS   8
#define CC1101_GDO0     13

const byte wmbus_cc1101_init[] = {
    {0x0B, 0x06}, {0x0D, 0x21}, {0x0E, 0x65}, {0x0F, 0x6A},
    {0x10, 0xF8}, {0x11, 0x83}, {0x12, 0x06}, {0x15, 0x40},
    {0x18, 0x18}, {0x19, 0x16}, {0x1A, 0x6C}, {0x21, 0x56}, {0x25, 0x00}
};

void writeRegister(byte reg, byte value) {
    digitalWrite(CC1101_SPI_CS, LOW);
    SPI.transfer(reg);
    SPI.transfer(value);
    digitalWrite(CC1101_SPI_CS, HIGH);
}

void sendStrobe(byte strobe) {
    digitalWrite(CC1101_SPI_CS, LOW);
    SPI.transfer(strobe);
    digitalWrite(CC1101_SPI_CS, HIGH);
}

void initCC1101() {
    sendStrobe(0x30);
    delay(10);
    for (int i = 0; i < sizeof(wmbus_cc1101_init) / 2; i++) {
        writeRegister(wmbus_cc1101_init[i], wmbus_cc1101_init[i]);
    }
    sendStrobe(0x34);
    Serial.println(F("[SYSTEM] CC1101 nasłuchuje..."));
}

// Przesyłanie danych przez lekkie gniazdo TCP (zamiast HTTPClient)
void sendFrameToCloud(const char* hexFrame) {
    if (WiFi.status() != WL_CONNECTED) return;

    WiFiClient client;
    // Łączymy się na port 80 do API wmbusmeters.org
    if (client.connect("wmbusmeters.org", 80)) {
        char postParam[150];
        snprintf(postParam, sizeof(postParam), "driver=auto&telegram=%s", hexFrame);

        client.println(F("POST /analyze HTTP/1.1"));
        client.println(F("Host: wmbusmeters.org"));
        client.println(F("Content-Type: application/x-www-form-urlencoded"));
        client.println(F("Accept: application/json"));
        client.print(F("Content-Length: "));
        client.println(strlen(postParam));
        client.println();
        client.print(postParam);

        unsigned long timeout = millis();
        while (client.available() == 0) {
            if (millis() - timeout > 4000) {
                client.stop();
                return;
            }
        }

        // Analiza odebranego strumienia bez używania biblioteki JSON
        while (client.available()) {
            String line = client.readStringUntil('\n');
            if (line.indexOf("{\"") != -1) { 
                Serial.println(F("\n===================================="));
                Serial.println(F(" -> ODEBRANO I ZDEKODOWANO RAMKĘ <-"));
                Serial.println(line); // Wypluwa czysty JSON z ID, Serialem i Odczytem
                Serial.println(F("===================================="));
            }
        }
        client.stop();
    }
}

void setup() {
    Serial.begin(115200);
    delay(2000);

    pinMode(PIN_POWER_EN, OUTPUT);
    pinMode(PIN_ANT_SW0, OUTPUT);
    pinMode(PIN_ANT_SW1, OUTPUT);
    digitalWrite(PIN_POWER_EN, HIGH);
    digitalWrite(PIN_ANT_SW0, HIGH);
    digitalWrite(PIN_ANT_SW1, LOW);
    delay(100);

    // Szybkie i lekkie uruchomienie Wi-Fi
    WiFi.mode(WIFI_STA);
    WiFi.begin(ssid, password);

    Serial.print(F("[WIFI] Łączenie"));
    int counter = 0;
    while (WiFi.status() != WL_CONNECTED && counter < 20) {
        delay(500);
        Serial.print(F("."));
        counter++;
    }
    Serial.println(F("\n[WIFI] Status połączenia aktywny."));

    pinMode(CC1101_SPI_CS, OUTPUT);
    digitalWrite(CC1101_SPI_CS, HIGH);
    SPI.begin(CC1101_SPI_CLK, CC1101_SPI_MISO, CC1101_SPI_MOSI, CC1101_SPI_CS);
    pinMode(CC1101_GDO0, INPUT);

    initCC1101();
}

void loop() {
    if (digitalRead(CC1101_GDO0) == HIGH) {
        digitalWrite(CC1101_SPI_CS, LOW);
        byte rxBytes = SPI.transfer(0x3B | 0x40);
        digitalWrite(CC1101_SPI_CS, HIGH);

        if (rxBytes > 0 && rxBytes < 64) {
            char hexFrame[130] = {0};
            char* ptr = hexFrame;

            digitalWrite(CC1101_SPI_CS, LOW);
            SPI.transfer(0x3F | 0x40);
            for (byte i = 0; i < rxBytes; i++) {
                byte b = SPI.transfer(0);
                ptr += sprintf(ptr, "%02x", b);
            }
            digitalWrite(CC1101_SPI_CS, HIGH);

            Serial.print(F("[RADIO] Złapano pakiet: "));
            Serial.println(hexFrame);

            sendFrameToCloud(hexFrame);
        }
        sendStrobe(0x36);
        sendStrobe(0x3A);
        sendStrobe(0x34);
    }
    delay(1);
}
